import sys; sys.path.insert(0,'/home/claude/ac-mdcu/parts')
from l22_common import mk, save
Q={}

mk(Q, 81, [62, 65, 68, 's7'],
 stem="A 28-year-old man has a tender, fluctuant 2-cm nodule on the thigh that began a week ago as a small pustule around a hair. What is the best treatment now?",
 opts=["Oral acyclovir","Excision with a wide skin margin","Reassurance and observation","Oral dicloxacillin alone","Incision and drainage"],
 interp="ตุ่มหนองที่รูขุมขน (folliculitis) ลุกลามลึกลงเป็นก้อนกดเจ็บ คลำได้ fluctuation ขนาด 2 cm = furuncle ที่มีหนองรวมเป็นโพรงแล้ว → ถามการรักษาที่ดีที่สุดตอนนี้ ต้องใช้หลักว่าหนองที่รวมเป็นโพรงต้องระบายออก ยาอย่างเดียวซึมเข้าโพรงหนองได้ไม่ดี",
 why="การติดเชื้อของรูขุมขนเรียงตามความลึก: <b>folliculitis</b> = ตุ่มหนองตื้นที่ปากรูขุมขน มักเกิดจาก <i>S. aureus</i> บางครั้งเป็น gram-negative เป็นน้อยหายเองได้ด้วยการรักษาความสะอาด → <b>furuncle (boil)</b> = การติดเชื้อลงลึกถึง dermis รอบรูขุมขนเดียว จนเกิดเป็น<b>ฝีที่มีหนองเป็นโพรง (abscess)</b> คลำได้ fluctuation → <b>carbuncle</b> = ฝีหลายรูขุมขนเชื่อมกันใต้ผิว มีหลายรูเปิด · เมื่อหนองรวมเป็นโพรงแล้ว ผนังโพรงและหนองที่ไม่มีเลือดไปเลี้ยงทำให้ยาเข้าไม่ถึง การรักษาหลักจึงเป็น <b>incision and drainage</b>: กรีดตรงจุดที่นุ่มที่สุด ระบายหนอง ทลาย loculation ล้างโพรง แล้วปล่อยให้แผลหายจากก้นขึ้นมา ส่งหนองเพาะเชื้อเมื่อเป็นซ้ำหรือสงสัย MRSA · IDSA 2014 ให้ I&amp;D อย่างเดียวพอในฝีทั่วไป และเพิ่ม<b>ยาปฏิชีวนะเมื่อมี SIRS</b> เซลลูไลติสรอบกว้าง ภูมิคุ้มกันต่ำ หรือระบายได้ไม่ครบ · การประคบอุ่นช่วยให้ฝีเล็กระยะแรกนุ่มลงและแตกระบายเองตามที่ชีทหน้า 7 กล่าว แต่ก้อน 2 cm ที่ fluctuant แล้วควรระบาย · สไลด์หน้า 65 ลายมือ <b>“Furuncle : abscess → I&amp;D”</b>",
 wrong={
  "A":"Acyclovir เป็นยาต้านไวรัสกลุ่ม herpes ใช้กับตุ่มน้ำใสเป็นกลุ่มบนฐานแดงจาก HSV หรือ VZV ไม่มีผลต่อฝีหนองจากแบคทีเรีย ก้อนที่เริ่มจากตุ่มหนองที่รูขุมขนแล้วกลายเป็นโพรงหนองเป็นภาพของ <i>S. aureus</i> · จะถูกถ้าหญิงพยาบาลมีตุ่มน้ำใสหลายตุ่มรวมกลุ่มที่ปลายนิ้วชี้ ปวดแสบมาก (herpetic whitlow) ซึ่งรักษาด้วย acyclovir และห้ามกรีดเพราะทำให้เชื้อลามและติดแบคทีเรียซ้ำ",
  "B":"การตัดกว้างรวมผิวหนังรอบ ๆ เป็นการรักษารอยโรคที่มี sinus tract เรื้อรังหรือเนื้อเยื่อติดเชื้อเป็นแผ่นกว้าง ฝีโพรงเดียวขนาด 2 cm หายได้ด้วยการกรีดระบาย การตัดกว้างทำให้แผลใหญ่ เสียผิวโดยไม่จำเป็น และไม่ลดการเป็นซ้ำ · จะถูกถ้าชายเป็น hidradenitis suppurativa ที่รักแร้มาหลายปี มี sinus tract เชื่อมกันเป็นร่างแหและแผลเป็นหนา (Hurley III) ซึ่งการระบายซ้ำไม่ได้ผล ต้องตัดผิวที่เป็นออกทั้งแผ่น",
  "C":"การรอดูเหมาะกับ folliculitis ตื้นไม่กี่ตุ่มที่ยังไม่เป็นโพรง ซึ่งมักยุบได้เองเมื่อรักษาความสะอาด แต่ก้อน fluctuant 2 cm คือหนองที่รวมเป็นโพรงแล้ว ปล่อยไว้จะปวดมากขึ้น ลามเป็นเซลลูไลติส หรือแตกเองแบบระบายไม่หมด · จะถูกถ้าชายมีตุ่มหนองเล็กสองสามตุ่มที่รูขุมขนบริเวณหนวดหลังโกนหนวด ไม่มีไข้ ไม่มีก้อนลึก ซึ่งดูแลความสะอาดแล้วเฝ้าดูได้",
  "D":"Dicloxacillin คลุม <i>S. aureus</i> ที่ไวต่อ methicillin จึงถูกเรื่องเชื้อ แต่ยากินอย่างเดียวซึมเข้าโพรงหนองได้น้อย ฝีที่มีโพรงจะหายช้าหรือไม่หายถ้าไม่ระบาย ยาเป็นเพียงส่วนเสริมเมื่อมีข้อบ่งชี้ · จะถูกถ้าชายมี folliculitis หลายสิบตุ่มกระจายทั่วต้นขาและก้น ไม่มีก้อนที่เป็นโพรง ซึ่งลายมือหน้า 62 ให้หลายเม็ดใช้ oral dicloxacillin"},
 trap="คำว่าเริ่มจากตุ่มหนองที่รูขุมขนชวนให้นึกถึง folliculitis แล้วเลือกยากินตามลายมือหน้า 62 หรือรอให้หายเอง · ตัวแยกคือ <b>fluctuation</b>: เมื่อคลำได้ก้อนนุ่มหยุ่นแปลว่าหนองรวมเป็นโพรงแล้ว ขั้นของโรคเปลี่ยนเป็น furuncle ซึ่งต้องระบาย ยาเป็นแค่ส่วนเสริม",
 summary=[
  "แกน: furuncle = ฝีที่มีหนองเป็นโพรงรอบรูขุมขนเดียว → incision and drainage เป็นการรักษาหลัก",
  "ลำดับความลึก: folliculitis (ปากรูขุมขน) → furuncle (ลงถึง dermis เป็นโพรง) → carbuncle (หลายรูขุมขนเชื่อมกัน หลายรูเปิด) ตามแผนภาพสไลด์หน้า 68",
  "ลายมือหน้า 62: folliculitis เป็นน้อยอาจหายเอง · หลายเม็ด → oral dicloxacillin · มักเป็นที่หนวดและรักแร้",
  "I&amp;D: กรีดตรงจุดนุ่มสุด ระบาย ทลาย loculation ล้างโพรง · ส่งเพาะเชื้อเมื่อเป็นซ้ำหรือไม่ตอบสนอง",
  "เพิ่มยาปฏิชีวนะเมื่อมี SIRS (ไข้ &gt; 38 °C ชีพจร &gt; 90 หายใจ &gt; 24) เซลลูไลติสรอบกว้าง ภูมิคุ้มกันต่ำ หรือฝีที่ใบหน้า มือ อวัยวะเพศ",
  "ประคบอุ่นช่วยฝีเล็กที่ยังไม่เป็นโพรงชัดให้นุ่มและแตกระบายเอง (ชีทหน้า 7)"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ก้อนที่คลำได้ fluctuation คือโพรงหนอง ตรงกับลายมือสไลด์หน้า 65 ที่ให้ furuncle ระบายด้วย I&amp;D และ IDSA 2014 ที่ให้ I&amp;D เป็นการรักษาหลักของ furuncle และฝี · จุดที่ควรรู้เพิ่ม: RCT ใน NEJM ปี 2016–2017 (Talan, Daum) พบว่าการให้ TMP-SMX หรือ clindamycin หลัง I&amp;D ในฝีขนาดเล็กเพิ่มอัตราหายเล็กน้อย บางแนวทางจึงพิจารณาให้ยาเป็นรายไป และในพื้นที่ที่มี MRSA ชุมชนสูง dicloxacillin ไม่คลุม · ชีทหน้า 7 เน้นการประคบอุ่นซึ่งเหมาะกับฝีเล็กระยะแรก ไม่ใช่ก้อน fluctuant ขนาด 2 cm",
 mnemonic="<b>‘Fluctuant = มีโพรงหนอง ต้องกรีด · ยาเป็นแค่ตัวเสริม’</b>",
 guide="IDSA Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections (Stevens et al., Clin Infect Dis 2014;59:e10–52); Sabiston Textbook of Surgery 21st ed. (2022) — Skin and soft tissue infections",
 variants=[
  "ชายมีฝีที่รูขุมขนเป็นซ้ำหลายครั้งทั้งในตัวเองและคนในบ้าน → ส่งหนองเพาะเชื้อหาเชื้อดื้อยา และพิจารณา decolonization ด้วย mupirocin ทาจมูกร่วมกับอาบน้ำ chlorhexidine",
  "เด็กมีฝีที่ข้างจมูก ตามด้วยไข้สูง หนังตาบวม ตาโปน กลอกตาไม่ได้ → cavernous sinus thrombosis จากเชื้อลามทาง facial vein ให้ยาปฏิชีวนะทางหลอดเลือดและถ่ายภาพสมอง",
  "ชายมีตุ่มหนองที่รูขุมขนทั่วลำตัวหลังแช่อ่างน้ำร้อนสาธารณะ 2 วัน → Pseudomonas (hot tub) folliculitis ซึ่งมักหายเองเมื่อเลี่ยงแหล่งน้ำ ไม่ต้องกรีด"])

mk(Q, 82, [67, 68, 's8'],
 stem="A 52-year-old diabetic woman had a carbuncle on her upper back drained through one small incision. Two days later pus still drains from several other openings. What should be done next?",
 opts=["Debridement of the involved skin and every pocket","Oral antibiotics alone until the openings close","Repeat the same small incision with oral antibiotics","Compression dressing over the drainage sites","Topical mupirocin to the lesions"],
 interp="Carbuncle ที่หลังในหญิงเบาหวาน ได้กรีดระบายแผลเล็กแผลเดียวแล้ว แต่หนองยังไหลจากรูอื่นหลายรู = ยังมี pocket ที่ไม่ได้ระบาย → ถามขั้นต่อไป ต้องใช้หลักว่า carbuncle เป็นฝีหลายโพรงเชื่อมกัน การกรีดจุดเดียวไม่ครบ ต้องเปิดและตัดเนื้อตายให้ทั่ว",
 why="<b>Carbuncle</b> คือการติดเชื้อของ<b>รูขุมขนหลายรูที่อยู่ติดกัน</b> หนองลามลงชั้นลึกใน dermis และไขมันใต้ผิวแล้วเชื่อมกันเป็นหลาย <b>pocket</b> คั่นด้วยผนังพังผืด และแตกออกที่ผิวเป็น<b>หลายรูเปิด (sinus)</b> คนไทยเรียก<b>ฝีฝักบัว</b> พบบ่อยที่ต้นคอด้านหลังและหลังส่วนบนซึ่งผิวหนา และในผู้ป่วยเบาหวาน · การกรีดแผลเล็กจุดเดียวระบายได้เพียงโพรงเดียว pocket อื่นยังคั่งหนองจึงยังไหลออกทางรูอื่น ผิวที่คลุมอยู่ก็มักขาดเลือดและตาย การรักษาจึงต้อง<b>เปิดแผลกว้าง ตัดผิวที่ตายและเนื้อเยื่อติดเชื้อออก ทลายผนังกั้นจนทุก pocket เปิดถึงกัน</b> ล้างแล้วปล่อยแผลเปิดให้หายเองหรือปิดภายหลัง ร่วมกับให้ยาปฏิชีวนะทั้งตัวที่คลุม <i>S. aureus</i> (พิจารณา MRSA) เพราะมีเบาหวานและการติดเชื้อกว้าง และต้องคุมระดับน้ำตาลให้ดี · ชีทหน้า 8 ให้การรักษาไว้สองระดับคือ incision and drainage หรือ <b>wide excision of infected tissue and sinuses</b> · สไลด์หน้า 67 ลายมือ <b>“= หลาย pockets ติดกัน → I&amp;D อาจไม่ครบทุก pockets → Debride skin เลย”</b>",
 wrong={
  "B":"ยาปฏิชีวนะชนิดกินจำเป็นในโจทย์นี้เพราะมีเบาหวานและติดเชื้อกว้าง แต่ยาอย่างเดียวเข้าไม่ถึง pocket หนองที่ยังไม่ได้เปิด การรอให้รูปิดเองจะยิ่งกักหนองไว้ข้างใน เสี่ยงลามเป็น sepsis · จะถูกถ้าชายสุขภาพดีมีผื่นแดงร้อนกดเจ็บที่หน้าแข้ง ขอบไม่ชัด ไม่มีหนองหรือโพรงคลำได้ ไม่มีไข้ (cellulitis ไม่ซับซ้อน) ซึ่งชีทหน้า 8 ให้ยาปฏิชีวนะชนิดกินก็พอ",
  "C":"การกรีดซ้ำจุดเดิมเพิ่มยากินเป็นการแก้ฝีโพรงเดียวที่ปากแผลปิดเร็วจนหนองคั่งกลับ แต่ปัญหาของ carbuncle คือ pocket อื่นที่ไม่เคยถูกเปิด แผลเล็กจุดเดิมจึงยังระบายไม่ครบเหมือนเดิม · จะถูกถ้าหญิงมี furuncle โพรงเดียวที่ก้นซึ่งกรีดระบายไปแล้ว ปากแผลแคบปิดเร็วใน 2 วันจนหนองคั่งในโพรงเดิม ไม่มีรูเปิดอื่น ซึ่งเปิดแผลเดิมระบายซ้ำและให้ยาร่วมได้",
  "D":"การพันกดใช้ลดบวมและช่วยการหายของแผลจากหลอดเลือดดำ หรือหยุดเลือดซึม การกดทับแผลที่ยังมีหนองคั่งทำให้หนองไหลออกยากขึ้นและเนื้อเยื่อขาดเลือดมากขึ้นในผู้ป่วยเบาหวาน · จะถูกถ้าหญิงมีแผลเรื้อรังเหนือตาตุ่มด้านในจาก venous insufficiency ผิวรอบแผลคล้ำ ABI ปกติ ไม่มีการติดเชื้อลึก ซึ่ง compression therapy เป็นการรักษาหลัก",
  "E":"Mupirocin ทาเฉพาะที่ใช้กับการติดเชื้อตื้นระดับ epidermis ยาซึมไม่ถึงหนองที่อยู่ลึกใน dermis และไขมันใต้ผิว ทั้งไม่แก้ปัญหา pocket ที่ยังปิดอยู่ · จะถูกถ้าเด็กอายุ 5 ปีมี impetigo ไม่กี่จุดรอบจมูก เป็นสะเก็ดสีน้ำผึ้ง ไม่มีไข้ ซึ่ง IDSA ให้ mupirocin หรือ retapamulin ทาเฉพาะที่ได้"},
 trap="การได้กรีดระบายไปแล้วทำให้รู้สึกว่าทำครบ เหลือแค่เพิ่มยาหรือกรีดซ้ำ · ตัวชี้คือหนองยังไหลจาก<b>รูอื่นหลายรู</b> ซึ่งแปลว่ามี pocket ที่ยังไม่ได้เปิด ไม่ใช่เชื้อดื้อยา คำตอบจึงเป็นการขยายการผ่าตัดให้ถึงทุก pocket ไม่ใช่เปลี่ยนยา",
 summary=[
  "แกน: carbuncle = ฝีหลายรูขุมขนเชื่อมกันเป็นหลาย pocket · กรีดจุดเดียวไม่ครบ → debride ผิวที่ตายและเปิดทุก pocket",
  "ลักษณะ: ก้อนแข็งกว้าง ปวด หลายรูเปิดมีหนองไหล (ฝีฝักบัว) · มักที่ต้นคอด้านหลังและหลังส่วนบนซึ่งผิวหนา",
  "ปัจจัยเสี่ยง: เบาหวาน อ้วน ภูมิคุ้มกันต่ำ · ต้องคุมน้ำตาลร่วมด้วย",
  "ต่างจาก furuncle ตรงที่มักมีไข้ อ่อนเพลีย และต้องให้ยาปฏิชีวนะทั้งตัวร่วมกับการผ่าตัด",
  "ชีทหน้า 8: I&amp;D หรือ wide excision of infected tissue and sinuses · แผนภาพสไลด์หน้า 68: carbuncle = cluster of boils",
  "หลังผ่าตัด: ปล่อยแผลเปิด ทำแผลจนมี granulation แล้วปล่อยหายเองหรือปิดภายหลัง"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจสูง — หนองยังไหลจากหลายรูหลังกรีดจุดเดียวตรงกับลายมือสไลด์หน้า 67 ที่บอกว่า I&amp;D อาจไม่ครบทุก pocket ให้ debride skin เลย และลายมือสไลด์หน้า 68 ที่ให้หลายรูเปิดต้อง debride · ชีทหน้า 8 ให้ทั้ง I&amp;D และ wide excision เป็นทางเลือก ขณะที่ IDSA 2014 จัด carbuncle ร่วมกับฝีโดยให้ I&amp;D เป็นหลัก และให้ยาปฏิชีวนะทั้งตัวเมื่อมี SIRS หรือภูมิคุ้มกันต่ำ ซึ่งเบาหวานที่คุมไม่ดีเข้าข่าย · แนวปฏิบัติจริงคือเปิดให้กว้างพอถึงทุก pocket และตัดเฉพาะผิวที่ตายแล้ว ไม่จำเป็นต้องตัดผิวดีรอบ ๆ ออกกว้าง",
 mnemonic="<b>‘หลายรู = หลาย pocket = เปิดให้หมด’</b>",
 guide="IDSA Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections (Stevens et al., Clin Infect Dis 2014); Sabiston Textbook of Surgery 21st ed. (2022) — Surgical infections",
 variants=[
  "หลัง debride carbuncle ที่หลังในผู้ป่วยเบาหวาน แผลเปิดกว้าง 8 cm มี granulation ดีในสัปดาห์ที่ 2 → ปิดด้วย split-thickness skin graft หรือรอให้หายเองตามขนาดแผล",
  "ชายเบาหวานมี carbuncle ที่ต้นคอร่วมกับไข้ 39 °C ชีพจร 112 → ให้ยาปฏิชีวนะทางหลอดเลือดที่คลุม MRSA เช่น vancomycin ร่วมกับผ่าตัด และเพาะเชื้อจากหนองและเลือด",
  "ชายอายุ 50 ปีไม่เคยตรวจสุขภาพ เป็น carbuncle ครั้งแรก → ตรวจระดับน้ำตาลและ HbA1c เพราะ carbuncle อาจเป็นอาการนำของเบาหวานที่ยังไม่ได้วินิจฉัย"])

mk(Q, 83, [7, 70],
 stem="A 66-year-old man has a 1.5-cm dome-shaped nodule on the forearm that grew within 6 weeks and has a central keratin-filled crater. What is the most likely diagnosis?",
 opts=["Keratoacanthoma","Seborrheic keratosis","Nevus sebaceous","Neurofibroma","Molluscum contagiosum"],
 interp="ผู้สูงอายุมีก้อนรูปโดมที่แขนซึ่งเป็นผิวถูกแดด โตเร็วภายในไม่กี่สัปดาห์ ตรงกลางเป็นปล่องมี keratin อุด → ถามการวินิจฉัย ต้องใช้ลักษณะเฉพาะสามอย่างของ keratoacanthoma: โตเร็ว รูปปล่องภูเขาไฟ และมีแกน keratin",
 why="<b>Keratoacanthoma (KA)</b> เป็นเนื้องอกของเซลล์ squamous ที่มาจากรูขุมขน พบในผู้สูงอายุบน<b>ผิวที่ถูกแดด</b> เช่น หน้า หลังมือ แขน มีการดำเนินโรคเฉพาะ 3 ระยะ: <b>โตเร็วมากในเวลา 2–8 สัปดาห์</b> จนได้ขนาดราว 1–2 cm → คงที่ → อาจ<b>ยุบเองในหลายเดือน</b>เหลือแผลเป็นบุ๋ม · รูปร่างเป็นก้อนโดมสีผิวหรือชมพู ขอบเรียบมัน ตรงกลาง<b>บุ๋มเป็นปล่องภูเขาไฟ (crater) มีแกน keratin อุด</b> · ลักษณะนี้คล้าย well-differentiated SCC มากทั้งทางคลินิกและพยาธิ หลายสำนักจัด KA เป็นชนิดย่อยของ SCC จึงจัดการโดยตัดออกทั้งก้อนส่งตรวจ · ปัจจัยเสี่ยงอื่น: ยา BRAF inhibitor เดี่ยว ภูมิคุ้มกันต่ำ และกลุ่ม Muir–Torre syndrome · สไลด์หน้า 70 ลายมือมุมบนเขียน <b>“benign”</b> และภาพ D <b>“keratocanthoma”</b> · สไลด์หน้า 7 ลายมือ <b>“มี keratin อุดอยู่”</b> และ <b>“ปล่องภูเขาไฟ = ก้อนที่ตรงกลางบุ๋ม”</b>",
 wrong={
  "B":"Seborrheic keratosis เป็นเนื้องอก benign ของ keratinocyte ที่พบบ่อยในผู้สูงอายุเหมือนกัน แต่ลักษณะเป็นแผ่นนูนสีน้ำตาลถึงดำ ผิวขรุขระเหมือนแปะติดผิว (stuck-on) โตช้าเป็นปี ไม่มีปล่องตรงกลาง · จะถูกถ้าชายอายุ 70 ปีมีแผ่นนูนสีน้ำตาลผิวขรุขระมันเยิ้มหลายแผ่นที่หลัง ค่อย ๆ เพิ่มจำนวนมาหลายปี ดูเหมือนขี้ผึ้งแปะ ตรงกับภาพ A ของสไลด์หน้า 70",
  "C":"Nevus sebaceous เป็น hamartoma ของต่อมไขมันและรูขุมขนที่มีตั้งแต่เกิด พบที่หนังศีรษะและใบหน้า ลักษณะเป็นปื้นสีเหลืองส้ม ไม่มีผม ผิวเป็นตุ่มละเอียด ไม่ใช่ก้อนโตเร็วในผู้สูงอายุ · จะถูกถ้าเด็กหญิงอายุ 8 ปีมีปื้นนูนสีเหลืองส้มไม่มีผมขึ้นบนหนังศีรษะตั้งแต่แรกเกิด ผิวเป็นตุ่มเล็กติดกันคล้าย cobblestone ตรงกับภาพ B ของสไลด์หน้า 70",
  "D":"Neurofibroma เป็นเนื้องอก benign ของ nerve sheath ลักษณะเป็นตุ่มนุ่มสีผิว กดแล้วยุบลงไปในผิว (buttonhole sign) โตช้า ไม่มีแกน keratin หรือปล่องตรงกลาง · จะถูกถ้าหญิงอายุ 40 ปีมีตุ่มนุ่มสีผิวขนาด 5 mm ที่ลำตัว กดแล้วจมลงไปในผิว เป็นมาหลายปีโดยไม่เปลี่ยนแปลง ตรงกับภาพ C ที่ลายมือเขียนว่านุ่ม",
  "E":"Molluscum contagiosum มีรอยบุ๋มตรงกลาง (umbilicated) เหมือนกัน แต่เป็นตุ่มเล็ก 2–5 mm หลายเม็ด เกิดจาก poxvirus ติดต่อทางการสัมผัส พบบ่อยในเด็กหรือที่อวัยวะเพศในผู้ใหญ่ ไม่ใช่ก้อนเดี่ยว 1.5 cm ที่มีแกน keratin · จะถูกถ้าเด็กชายอายุ 4 ปีมีตุ่มโดมสีผิวมันวาวขนาด 3 mm หลายสิบเม็ดที่ลำตัวและข้อพับ ตรงกลางบุ๋ม บีบแล้วมีเนื้อขาวออก และพี่น้องเป็นด้วย"},
 trap="ตำแหน่งบนผิวที่ถูกแดดในผู้สูงอายุทำให้คิดถึงรอยโรคผิวสูงวัยอย่าง seborrheic keratosis และรอยบุ๋มกลางก้อนชวนนึกถึง molluscum · ตัวแยกคือ<b>ความเร็วในการโต</b>เป็นสัปดาห์ร่วมกับ<b>แกน keratin ในปล่อง</b> ซึ่งเป็นลายเซ็นของ KA ส่วน SK โตช้าเป็นปีและ molluscum เป็นตุ่มเล็กหลายเม็ด",
 summary=[
  "แกน: ก้อนโดมโตเร็วเป็นสัปดาห์ + ปล่องตรงกลางมี keratin อุด บนผิวถูกแดดของผู้สูงอายุ = keratoacanthoma",
  "ดำเนินโรค 3 ระยะ: โตเร็ว 2–8 สัปดาห์ → คงที่ → อาจยุบเองในหลายเดือน เหลือแผลเป็นบุ๋ม",
  "สไลด์หน้า 70 รวม benign 4 ภาพ: A seborrheic keratosis · B nevus sebaceous · C neurofibroma (นุ่ม) · D keratoacanthoma",
  "แยกจาก well-differentiated SCC ทางคลินิกไม่ได้ หลายสำนักถือเป็นชนิดย่อยของ SCC → ตัดส่งตรวจ",
  "ปัจจัยเสี่ยง: แดด อายุมาก ภูมิคุ้มกันต่ำ ยา BRAF inhibitor เดี่ยว · หลายก้อนร่วมกับเนื้องอกต่อมไขมันนึกถึง Muir–Torre",
  "ขนาดทั่วไป 1–2 cm · ชนิด giant โตเกิน 2–3 cm อาจทำลายโครงสร้างใกล้เคียง"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจสูง — สามลักษณะคือโตเร็วเป็นสัปดาห์ รูปปล่องภูเขาไฟ และแกน keratin ตรงกับลายมือสไลด์หน้า 7 และภาพ D ของสไลด์หน้า 70 · จุดที่ต่างจากตำราปัจจุบัน: สไลด์หน้า 70 จัด KA ไว้ในกลุ่ม benign แต่ WHO Classification of Skin Tumours (2018) และผู้เชี่ยวชาญจำนวนมากถือว่า KA เป็น SCC ชนิด keratoacanthoma-type ซึ่งบางก้อนลุกลามหรือแพร่กระจายได้ จึงไม่ควรวางใจแม้จะยุบเองได้ ลายมือสไลด์หน้า 7 ที่ให้ bx เมื่อสงสัย SCC จึงสอดคล้องกับแนวทางปัจจุบันมากกว่าคำว่า benign",
 mnemonic="<b>‘KA = ภูเขาไฟพ่น keratin ที่ขึ้นเร็วในไม่กี่สัปดาห์’</b>",
 guide="WHO Classification of Skin Tumours 4th ed. (2018); Bolognia Dermatology 4th ed. (2018) — Keratoacanthoma; NCCN Clinical Practice Guidelines in Oncology: Squamous Cell Skin Cancer (2025)",
 variants=[
  "ชาย melanoma ระยะลุกลามได้ vemurafenib เดี่ยว แล้วมีก้อนปล่อง keratin โตเร็วหลายก้อนใน 2 เดือน → KA และ cSCC จากยา BRAF inhibitor ตัดออก และการให้ร่วมกับ MEK inhibitor ช่วยลดการเกิด",
  "หญิงอายุ 60 ปีมี KA ขนาด 4 cm ที่ปลายจมูกซึ่งตัดแล้วจะผิดรูปมาก → พิจารณา Mohs surgery เพื่อเก็บเนื้อดีและตรวจขอบครบ",
  "ชายมี KA หลายสิบก้อนเป็นซ้ำตั้งแต่วัยหนุ่ม แต่ละก้อนยุบเองทิ้งแผลเป็นบุ๋ม และพ่อเป็นเหมือนกัน → Ferguson-Smith syndrome (multiple self-healing squamous epithelioma) ถ่ายทอดแบบ autosomal dominant"])

mk(Q, 84, [71, 72, 's14'],
 stem="A 30-year-old man has dozens of soft cutaneous nodules on the back, six café-au-lait macules and Lisch nodules on slit-lamp examination. Which problems require lifelong surveillance in this condition?",
 opts=["Pressure injuries over bony prominences","Keloid formation after minor trauma","Varicose veins of the lower limbs","Malignant tumors and hypertension","Basal cell carcinomas on sun-exposed skin"],
 interp="Neurofibroma หลายสิบก้อน + café-au-lait 6 จุด + Lisch nodules = ครบเกณฑ์ NF1 (ต้องมีอย่างน้อย 2 ข้อ) → ถามสิ่งที่ต้องเฝ้าระวังตลอดชีวิต ต้องรู้ว่า NF1 เป็น tumor predisposition syndrome ที่เพิ่มมะเร็งหลายชนิด และมีความดันโลหิตสูงได้จากหลายสาเหตุ",
 why="<b>NF1 (von Recklinghausen disease)</b> เกิดจากการกลายพันธุ์ของยีน <b>NF1 บนโครโมโซม 17</b> ซึ่งสร้าง neurofibromin ทำหน้าที่ยับยั้ง RAS เมื่อขาดหน้าที่นี้เซลล์จึงโตผิดปกติได้ง่าย เป็น<b>กลุ่มอาการเสี่ยงเนื้องอก</b>: ที่สำคัญที่สุดคือ <b>malignant peripheral nerve sheath tumor (MPNST)</b> ซึ่งมักเกิดจาก plexiform neurofibroma ความเสี่ยงตลอดชีวิตราว 8–13% (สงสัยเมื่อก้อนโตเร็ว ปวดต่อเนื่อง แข็งขึ้น หรือมีอาการทางประสาท) · <b>optic pathway glioma</b> ราว 15% ของเด็ก ส่วนใหญ่ก่อนอายุ 6 ปี · มะเร็งเต้านมในหญิงอายุน้อย GIST pheochromocytoma และ JMML ในเด็ก · <b>ความดันโลหิตสูง</b>ส่วนใหญ่เป็นชนิด primary แต่ต้องหา <b>renal artery stenosis</b> ในเด็กและผู้ใหญ่อายุน้อย และ <b>pheochromocytoma</b> โดยเฉพาะเมื่อความดันขึ้นเป็นพักหรือขณะตั้งครรภ์ · การติดตามจึงเน้นตรวจร่างกายทุกปี วัดความดันทุกครั้ง ตรวจตาทุกปีในเด็ก และประเมินก้อนที่เปลี่ยนแปลง · สไลด์หน้า 72 <b>“Increases risk of : ✓ Malignancies · ✓ Primary HTN · ✓ Learning disabilities · ✓ Seizures”</b> และ <b>“Follow up : ✓ Annual vision exam · ✓ BP monitoring · ✓ Annual full physical examination · ✓ Tumor surveillance”</b>",
 wrong={
  "A":"แผลกดทับเกิดจากแรงกดเหนือปุ่มกระดูกในผู้ที่พลิกตัวเองไม่ได้หรือไม่มีความรู้สึก ไม่ได้เป็นผลของ NF1 โดยตรง ผู้ป่วย NF1 ส่วนใหญ่เคลื่อนไหวได้ปกติ จึงไม่ใช่ปัญหาที่ต้องเฝ้าระวังประจำ · จะถูกถ้าชายอายุ 30 ปีเป็นอัมพาตครึ่งล่างจากการบาดเจ็บไขสันหลังระดับ T10 นั่งรถเข็นทั้งวัน ซึ่งต้องเฝ้าระวังแผลกดทับที่ ischial tuberosity และ sacrum ตลอดชีวิต",
  "B":"Keloid เกิดจากการสร้างคอลลาเจนเกินขอบแผลเดิม พบมากในคนผิวเข้ม ตำแหน่งเสี่ยงคือติ่งหู หน้าอก ไหล่ และมีแนวโน้มทางพันธุกรรมของตัวเอง ไม่ได้เพิ่มขึ้นใน NF1 · จะถูกถ้าหญิงอายุ 25 ปีเคยเกิด keloid ก้อนใหญ่ที่ติ่งหูหลังเจาะหู และแม่เป็น keloid ง่าย ซึ่งต้องระวัง keloid ทุกครั้งที่มีแผลหรือผ่าตัด และพิจารณาฉีด steroid ป้องกันหลังผ่าตัด",
  "C":"Varicose veins เป็นโรคของหลอดเลือดดำผิวตื้นจากลิ้นรั่ว ความผิดปกติของหลอดเลือดใน NF1 เป็นของหลอดเลือดแดง เช่น renal artery stenosis หรือ aneurysm ไม่ใช่หลอดเลือดดำขา · จะถูกถ้าเด็กชายมีปานแดงเป็นแผ่นที่ขาข้างเดียว ขาข้างนั้นยาวและโตกว่าอีกข้าง (Klippel–Trenaunay syndrome) ซึ่งต้องเฝ้าระวังเส้นเลือดดำขอดผิดปกติและหลอดเลือดดำอุดตันที่ขาข้างนั้นตลอดชีวิต",
  "E":"BCC บนผิวที่ถูกแดดเพิ่มขึ้นตามแดดสะสม ผิวขาว หรือกลุ่มอาการที่ซ่อมแซม DNA บกพร่อง NF1 ไม่ได้เพิ่ม BCC เนื้องอกที่เพิ่มคือของเส้นประสาท สมอง เต้านม และทางเดินอาหาร · จะถูกถ้าเด็กหญิงที่ไวต่อแสงแดดมาก ผิวไหม้ง่ายตั้งแต่ขวบแรก มีกระเต็มหน้า (xeroderma pigmentosum) ซึ่งต้องเฝ้าระวัง BCC, SCC และ melanoma บนผิวที่ถูกแดดตลอดชีวิต"},
 trap="Neurofibroma บนผิวหลายสิบก้อนดึงให้คิดถึงปัญหาผิวหนังทั่วไปอย่าง BCC หรือ keloid · ตัวแยกคือ NF1 เป็นโรคพันธุกรรมที่ยีนกดเนื้องอกเสียทั้งตัว ความเสี่ยงจึงเป็น<b>มะเร็งของเนื้อเยื่อประสาทและอวัยวะอื่น</b>ร่วมกับ<b>ความดันสูง</b> ไม่ใช่มะเร็งผิวจากแดด",
 summary=[
  "แกน: NF1 = tumor predisposition syndrome → เฝ้าระวังมะเร็ง (MPNST, optic glioma, เต้านม, GIST, pheochromocytoma) และความดันโลหิตสูงตลอดชีวิต",
  "สไลด์หน้า 72: เพิ่มเสี่ยง malignancy · primary HTN · learning disability · seizure · ติดตาม: ตรวจตาทุกปี วัดความดัน ตรวจร่างกายทุกปี tumor surveillance",
  "MPNST: ความเสี่ยงตลอดชีวิตราว 8–13% (ชีทหน้า 14 ให้ neurofibroma เป็นมะเร็ง 8–16%) · สงสัยเมื่อก้อนโตเร็ว ปวดต่อเนื่อง แข็งขึ้น → MRI ± PET แล้ว biopsy",
  "ความดันสูง: ส่วนใหญ่ primary · หา renal artery stenosis ในคนอายุน้อย และ pheochromocytoma เมื่อขึ้นเป็นพัก",
  "หญิง NF1: คัดกรองมะเร็งเต้านมด้วย mammography ทุกปีตั้งแต่อายุ 30 ปี และพิจารณา MRI เต้านมช่วงอายุ 30–50 ปี (NCCN)",
  "เด็ก: optic pathway glioma ราว 15% ส่วนใหญ่ก่อนอายุ 6 ปี → ตรวจตาทุกปีจนถึงราวอายุ 8 ปี แล้วห่างขึ้น"],
 opinion="เห็นด้วยกับคำตอบ D ความมั่นใจสูง — สไลด์หน้า 72 ระบุ malignancies และ primary HTN ในรายการความเสี่ยง และ follow up ด้วยการวัดความดันกับ tumor surveillance ตรงตัว · จุดที่ต่างจากแนวทางปัจจุบัน: เกณฑ์วินิจฉัยบนสไลด์หน้า 71 และ 72 เป็นเกณฑ์ NIH 1988 ซึ่ง Legius และคณะปรับปรุงในปี 2021 โดยเพิ่ม pathogenic NF1 variant และ choroidal abnormalities และกำหนดว่าถ้ามีเพียง café-au-lait กับ freckling อย่างน้อยหนึ่งอย่างต้องเป็นสองข้าง · คำว่า primary HTN บนสไลด์ไม่ควรทำให้ลืมหา renal artery stenosis และ pheochromocytoma · ชีทหน้า 14 ให้ neurofibroma กลายเป็นมะเร็ง 8–16% ซึ่งสูงกว่าที่ตำราใหม่ประเมินสำหรับ MPNST ตลอดชีวิต (ราว 8–13%) เล็กน้อย",
 mnemonic="<b>‘NF1 เฝ้า 3 อย่าง: ก้อน (มะเร็ง) · ตา (glioma) · ความดัน’</b>",
 guide="Legius E, et al. Revised diagnostic criteria for neurofibromatosis type 1 and Legius syndrome (Genet Med 2021;23:1506–13); Miller DT, et al. Health supervision for children with neurofibromatosis type 1 (Pediatrics 2019;143:e20190660); NCCN Guidelines: Genetic/Familial High-Risk Assessment: Breast, Ovarian, and Pancreatic (2025)",
 variants=[
  "หญิง NF1 อายุ 32 ปีมี plexiform neurofibroma ที่ต้นขาซึ่งคงที่มาหลายปี แต่ 2 เดือนนี้โตเร็วและปวดตอนกลางคืน → สงสัย MPNST ทำ MRI ร่วมกับ FDG-PET แล้ว biopsy ส่วนที่ uptake สูง",
  "เด็ก NF1 อายุ 4 ปีตามัวข้างเดียวและตาโปน → optic pathway glioma ทำ MRI สมองและเบ้าตา",
  "เด็ก NF1 อายุ 5 ปีมี plexiform neurofibroma ที่คอซึ่งผ่าตัดออกไม่ได้และกดทางเดินหายใจ → selumetinib (MEK inhibitor) เป็นยาที่ได้รับอนุมัติสำหรับกรณีนี้",
  "ชาย NF1 อายุ 45 ปีถ่ายดำและซีด ส่องกล้องบนและล่างไม่พบแผล → นึกถึง GIST ของลำไส้เล็ก ทำ CT"])

mk(Q, 85, [43, 45, 's17'],
 stem="A 70-year-old has a 1-cm, well-defined, primary nodular basal cell carcinoma on the back. Which NCCN clinical margin applies?",
 opts=["About 3 cm","About 4 mm","About 1 mm","No margin beyond the visible edge","About 2 cm"],
 interp="BCC ชนิด nodular ขนาด 1 cm ที่ลำตัว ขอบชัด เป็นครั้งแรก = BCC ความเสี่ยงต่ำตาม NCCN → ถามขอบตัดทางคลินิกที่แนะนำ ต้องรู้ว่า BCC โตช้าและแทบไม่แพร่กระจาย ขอบแคบระดับมิลลิเมตรก็ควบคุมได้ และเทียบกับขอบ 0.5 cm ที่ลายมือให้ไว้",
 why="BCC เป็นมะเร็งผิวที่<b>ลุกลามเฉพาะที่และแพร่กระจายน้อยมาก</b> (&lt; 0.1%) เป้าหมายจึงอยู่ที่การตัดก้อนออกให้หมดในครั้งแรก · NCCN แบ่ง BCC เป็นความเสี่ยงต่ำและสูงตาม<b>ตำแหน่ง ขนาด ขอบเขต การเป็นครั้งแรกหรือซ้ำ ภูมิคุ้มกัน ประวัติฉายรังสี ชนิดทางพยาธิ และ perineural invasion</b>: ก้อนที่ลำตัวหรือแขนขา &lt; 2 cm ขอบชัด เป็นครั้งแรก ชนิด nodular หรือ superficial จัดเป็น<b>ความเสี่ยงต่ำ</b> · สำหรับกลุ่มนี้ NCCN แนะนำ <b>standard excision ด้วยขอบทางคลินิก 4 mm</b> และตรวจขอบทางพยาธิหลังผ่าตัด ซึ่งล้างก้อน BCC ขนาดต่ำกว่า 2 cm ได้ราว 95% หรือเลือก curettage and electrodesiccation ในบริเวณที่ไม่มีขน · กลุ่มความเสี่ยงสูง เช่น ก้อนที่หน้าส่วนกลาง ขอบไม่ชัด ชนิด morpheaform หรือเป็นซ้ำ ใช้ <b>Mohs surgery</b> หรือการตัดที่ตรวจขอบครบ · ตัวเลข 4 mm ใกล้เคียงกับ 5 mm ที่ใช้ดั้งเดิม ชีทหน้า 17 ให้ขอบ <b>5 มม.</b> ได้ cure rate 98% ใน primary lesion และ 80% ใน recurrence lesion · สไลด์หน้า 45 ลายมือ <b>“basal cell (less aggressive) = ขอ margin 0.5 cm”</b>",
 wrong={
  "A":"ขอบราว 3 cm กว้างเกินแนวทางปัจจุบันของมะเร็งผิวชนิดหลักทุกชนิด และถ้าใช้กับ BCC ขนาด 1 cm จะได้แผลกว้างราว 7 cm ต้องปิดด้วย graft หรือ flap โดยไม่เพิ่มการหายขาด · ไม่มีสถานการณ์ใดที่แนวทาง NCCN ปัจจุบันของ BCC, cSCC หรือ melanoma ให้ขอบราว 3 cm เพราะแม้ melanoma ที่หนาเกิน 2 mm ซึ่งต้องการขอบกว้างที่สุดก็ใช้สูงสุด 2 cm และ RCT พบว่าขอบที่กว้างกว่านั้นไม่เพิ่มการรอดชีวิต",
  "C":"ขอบราว 1 mm ไม่พอคุม BCC เพราะเซลล์มะเร็งลามใต้ผิวเกินขอบที่มองเห็นเป็นแขนงเล็ก ๆ ขอบแคบระดับนี้ใช้เพื่อวินิจฉัย ไม่ใช่รักษา · จะถูกถ้าหญิงมีไฝสีไม่สม่ำเสมอขนาด 7 mm ที่ต้นแขนซึ่งสงสัย melanoma และยังไม่มีผลชิ้นเนื้อ ซึ่ง NCCN แนะนำ excisional biopsy ขอบแคบ 1–3 mm เพื่อให้วัดความหนาได้ครบก่อนวางแผนตัดกว้าง",
  "D":"การตัดชิดขอบที่เห็นโดยไม่เผื่อขอบจะเหลือเซลล์มะเร็งที่ลามใต้ผิวเกินขอบสายตา ทำให้ขอบบวกและเป็นซ้ำ แม้ Mohs surgery ซึ่งตัดชั้นแรกแคบมากก็ยังเผื่อขอบ 1–2 mm และตรวจขอบครบทุกด้าน · ไม่มีสถานการณ์ใดที่ NCCN แนะนำให้รักษามะเร็งผิวหนังด้วยการตัดชิดขอบที่มองเห็นโดยไม่เผื่อขอบ เพราะทุกวิธีที่ใช้รักษาต้องได้ขอบปลอดเนื้องอก",
  "E":"ขอบราว 2 cm เป็นขอบของเนื้องอกที่แพร่กระจายได้สูงและต้องการเก็บ micrometastasis รอบก้อน ไม่จำเป็นสำหรับ BCC ความเสี่ยงต่ำที่ลามเพียงไม่กี่มิลลิเมตรจากขอบที่เห็น · จะถูกถ้าชายมี melanoma ที่หลังซึ่งผล excisional biopsy หนา 3 mm (Breslow &gt; 2 mm) ซึ่ง NCCN แนะนำ wide local excision ขอบทางคลินิก 2 cm"},
 trap="ลายมือให้ BCC ขอบ 0.5 cm ทำให้ลังเลเมื่อไม่มีตัวเลขนี้ในช้อย และ 2 cm ก็คุ้นจาก melanoma · ตัวแยกคือ<b>หน่วย</b>: BCC ความเสี่ยงต่ำใช้ขอบระดับมิลลิเมตร (4 mm ≈ 0.4 cm ใกล้ 0.5 cm) ส่วนขอบระดับเซนติเมตรเป็นของ melanoma และของ SCC ตามลายมือ (1 cm)",
 summary=[
  "แกน: BCC ความเสี่ยงต่ำ (NCCN) → standard excision ขอบทางคลินิก 4 mm + ตรวจขอบทางพยาธิ",
  "ความเสี่ยงต่ำ: ลำตัวหรือแขนขา &lt; 2 cm (ยกเว้นหน้าแข้ง มือ เท้า ข้อเท้า เล็บ) · ขอบชัด · เป็นครั้งแรก · nodular หรือ superficial · ไม่มี perineural invasion · ภูมิคุ้มกันปกติ · ไม่เคยฉายรังสี",
  "ความเสี่ยงสูง → Mohs surgery หรือการตัดที่ตรวจขอบครบ (PDEMA) · ผู้ที่ผ่าตัดไม่ได้: ฉายรังสี",
  "ขอบ 4 mm ล้างก้อน BCC &lt; 2 cm ได้ราว 95% (Wolf &amp; Zitelli 1987)",
  "ลายมือสไลด์หน้า 43 และ 45: BCC ขอบ 0.5 cm · SCC ขอบ 1 cm · ชีทหน้า 17: ขอบ 5 มม. cure rate 98% ใน primary lesion",
  "เทียบ cSCC ความเสี่ยงต่ำ NCCN 4–6 mm · melanoma ขอบสูงสุด 2 cm"],
 opinion="เห็นด้วยกับคำตอบ B ความมั่นใจสูง — NCCN Basal Cell Skin Cancer (2025) ให้ขอบทางคลินิก 4 mm สำหรับ standard excision ของ BCC ความเสี่ยงต่ำ และก้อนในโจทย์เข้าเกณฑ์ทุกข้อ (ลำตัว &lt; 2 cm ขอบชัด เป็นครั้งแรก nodular) · จุดที่ต่างจากแนวทางปัจจุบัน: ลายมือสไลด์หน้า 43 และ 45 ให้ BCC ขอบ 0.5 cm ทุกก้อนโดยไม่แยกความเสี่ยง และชีทหน้า 17 ก็ใช้ 5 มม. เป็นค่ามาตรฐาน ซึ่งใกล้เคียงสำหรับก้อนความเสี่ยงต่ำ แต่ก้อนความเสี่ยงสูงปัจจุบันควรใช้ Mohs หรือการตัดที่ตรวจขอบครบแทนการเพิ่มขอบตายตัว",
 mnemonic="<b>‘BCC low-risk 4 mm · cSCC low-risk 4–6 mm · melanoma สูงสุด 2 cm’</b>",
 guide="NCCN Clinical Practice Guidelines in Oncology: Basal Cell Skin Cancer (2025); Wolf DJ, Zitelli JA. Surgical margins for basal cell carcinoma (Arch Dermatol 1987;123:340–4)",
 variants=[
  "หญิงมี superficial BCC ขนาด 8 mm ที่ต้นแขน ไม่ต้องการผ่าตัด → imiquimod หรือ 5-FU ทาเฉพาะที่เป็นทางเลือกได้ แม้อัตราหายขาดต่ำกว่าการผ่าตัด",
  "ชายมี morpheaform BCC ที่ข้างจมูก ขอบไม่ชัด → ความเสี่ยงสูง ส่ง Mohs surgery เพื่อตรวจขอบครบและเก็บเนื้อดี",
  "หลังตัด BCC ความเสี่ยงต่ำที่หลังด้วยขอบ 4 mm ผลพยาธิพบขอบบวก → ตัดซ้ำให้ขอบปลอดหรือทำ Mohs ไม่ปล่อยรอดูในก้อนที่ตัดซ้ำได้",
  "ชายอายุ 85 ปีมี BCC ขนาด 2.5 cm ที่หนังตาล่างและปฏิเสธการผ่าตัด → ฉายรังสีเป็นการรักษาทางเลือก"])

mk(Q, 86, [8, 9, 's11'],
 stem="A 30-year-old woman has a 1-cm mole on the thigh that has been present since birth. Over 3 months it has darkened and become itchy. What is the best management?",
 opts=["Topical corticosteroid for the itching","Photograph and review it in three months","Reassurance, since congenital moles stay benign throughout life","Excisional biopsy of the nevus for histology","Electrocautery ablation without histology"],
 interp="ไฝแต่กำเนิดขนาด 1 cm (small CMN) ในผู้ใหญ่ เพิ่งมีสีเข้มขึ้นและคันใน 3 เดือน = cardinal sign 2 ข้อของการเปลี่ยนเป็นมะเร็ง → ถามการจัดการที่ดีที่สุด ต้องใช้หลักว่า CMN มีความเสี่ยง melanoma และไฝที่เปลี่ยนต้องได้ชิ้นเนื้อทั้งก้อน",
 why="<b>Congenital melanocytic nevus (CMN)</b> พบราว 1% ของทารก แบ่งตามขนาดที่คาดเมื่อเป็นผู้ใหญ่: small &lt; 1.5 cm · medium 1.5–20 cm · large 20–40 cm · giant &gt; 40 cm · ความเสี่ยง melanoma สูงตามขนาด: CMN ขนาด large และ giant เสี่ยงตลอดชีวิตราว 2–5% มักเกิดตั้งแต่วัยเด็กและอาจอยู่ในชั้นลึก ส่วน small และ medium เสี่ยงต่ำกว่า 1% และมักเกิดหลังวัยรุ่นที่รอยต่อ dermis–epidermis ซึ่งมองเห็นการเปลี่ยนแปลงได้ · เมื่อไฝใดมี <b>cardinal sign</b> เช่น ขนาด รูปร่าง ความหนาเปลี่ยน สีเปลี่ยน คัน เลือดออก ต้อง<b>ตัดชิ้นเนื้อทั้งก้อน (excisional biopsy) ขอบแคบ 1–3 mm ลึกถึงไขมันใต้ผิว</b> เพื่อให้พยาธิแพทย์วัดความหนา Breslow ได้ครบ ไม่ใช้การจี้ การเลเซอร์ หรือ shave ตื้นที่ทำลายชิ้นเนื้อ · CMN ขนาด 1 cm ตัดและเย็บปิดได้ในครั้งเดียว · ชีทหน้า 11 <b>“Congenital melanocytic nevus (giant hairy nevus) พบได้ประมาณ 1 % ในทารกแรกเกิด”</b> · สไลด์หน้า 8 ลายมือ <b>“congenital จะเสี่ยง melanoma”</b> และ <b>“สงสัย CA ถ้ามี cardinal symptoms”</b>",
 wrong={
  "A":"Steroid ทาลดอาการคันได้ แต่อาการคันที่เกิดกับไฝที่สีเข้มขึ้นเป็น cardinal sign ของการเปลี่ยนเป็นมะเร็ง ไม่ใช่ผื่นอักเสบ การทายาจะกลบอาการและทำให้วินิจฉัยช้า · จะถูกถ้าหญิงมีผื่นแดงคันขุยที่ข้อพับทั้งสองข้างจาก atopic dermatitis กำเริบ โดยไฝที่อยู่ใกล้กันมีขนาดและสีคงเดิมมาหลายปี ซึ่งรักษาผื่นด้วย topical corticosteroid",
  "B":"การถ่ายภาพแล้วนัดดูอีก 3 เดือน (short-term digital monitoring) ใช้กับไฝแบนที่ดูก้ำกึ่งเล็กน้อยใน dermoscopy โดยผู้ป่วยไม่ได้สังเกตการเปลี่ยนแปลง ไฝที่ผู้ป่วยบอกชัดว่าสีเข้มขึ้นและคันเข้าเกณฑ์ตัดตรวจแล้ว · จะถูกถ้าชายที่มีไฝจำนวนมากมาตรวจคัดกรอง พบไฝแบนเม็ดหนึ่งมีลักษณะไม่ปกติเล็กน้อยใน dermoscopy ไม่มีอาการและไม่เคยเปลี่ยน ซึ่งถ่ายภาพไว้เทียบใน 3 เดือนได้",
  "C":"เหตุผลในช้อยผิด: CMN ไม่ได้ benign ตลอดชีวิต ทุกขนาดมีความเสี่ยง melanoma สูงกว่าไฝทั่วไป และไฝแต่กำเนิดที่มี cardinal sign ต้องตัดตรวจ · ไม่มีสถานการณ์ใดที่การให้คำมั่นว่าไฝแต่กำเนิดจะไม่กลายเป็นมะเร็งตลอดชีวิตถูกต้อง เพราะลายมือสไลด์หน้า 8 และตำราทุกเล่มระบุว่า congenital nevus เสี่ยง melanoma แม้ small CMN ที่คงที่จะเฝ้าดูได้ก็ต้องสอนให้สังเกตการเปลี่ยนแปลงต่อไป",
  "E":"การจี้ไฟฟ้าทำลายเนื้อเยื่อจนไม่มีชิ้นเนื้อส่งตรวจ ถ้ารอยโรคเป็น melanoma จะไม่รู้ความหนา Breslow ไม่รู้ระยะ วางแผนตัดกว้างไม่ได้ และอาจเหลือเซลล์ในชั้นลึก · จะถูกถ้าชายมีติ่งเนื้อ (skin tag) ขนาด 2 mm หลายอันที่คอ ลักษณะชัดเจน ไม่มีอาการ ต้องการเอาออกเพื่อความสวยงาม ซึ่งจี้ด้วยไฟฟ้าได้โดยไม่ต้องส่งตรวจ"},
 trap="อาการคันชวนให้คิดว่าเป็นผื่นธรรมดาและให้ยาทา และความเชื่อว่าไฝติดตัวมาแต่เกิดไม่อันตรายทำให้วางใจ · ตัวแยก: ไฝแต่กำเนิด<b>เสี่ยง melanoma มากกว่าไฝที่เกิดภายหลัง</b> และ<b>สีเปลี่ยนกับคันเป็น cardinal sign</b>คนละข้อกัน มีเพียงข้อเดียวก็พอให้ตัดตรวจ",
 summary=[
  "แกน: CMN ที่มี cardinal sign (สีเปลี่ยน คัน) → excisional biopsy ทั้งก้อน ขอบ 1–3 mm ส่งตรวจ",
  "CMN พบราว 1% ของทารก · ขนาดคาดเมื่อเป็นผู้ใหญ่: small &lt; 1.5 cm · medium 1.5–20 cm · large 20–40 cm · giant &gt; 40 cm (พบน้อยมาก)",
  "ความเสี่ยง melanoma: large และ giant ราว 2–5% เกิดเร็วในวัยเด็กและอาจอยู่ชั้นลึก · small และ medium &lt; 1% มักเกิดหลังวัยรุ่น",
  "ลายมือสไลด์หน้า 8: ไฝส่วนใหญ่ acquired ไม่เสี่ยง · congenital เสี่ยง melanoma · สงสัย CA เมื่อมี cardinal symptoms",
  "Cardinal signs สไลด์หน้า 9: surface marking หาย · ขนาด รูปร่าง ความหนาเปลี่ยน · สีเปลี่ยน · คัน · เลือดออกหรือเป็นแผล · halo · มีการกระจาย",
  "ไฝที่สงสัย: ห้ามจี้ ห้ามเลเซอร์ ห้ามทายากลบอาการ เพราะไม่ได้ชิ้นเนื้อหรือทำให้วินิจฉัยช้า"],
 opinion="เห็นด้วยกับคำตอบ D ความมั่นใจสูง — ไฝแต่กำเนิดที่สีเปลี่ยนและคันเข้าเกณฑ์ cardinal sign สองข้อของสไลด์หน้า 9 และลายมือสไลด์หน้า 8 ระบุว่า congenital เสี่ยง melanoma · NCCN Melanoma (2025) แนะนำ excisional biopsy ขอบ 1–3 mm สำหรับรอยโรคที่สงสัย · จุดที่ควรรู้: ชีทหน้า 11 ใช้หัวข้อ giant hairy nevus กับ CMN ทั้งกลุ่ม ซึ่งอาจทำให้เข้าใจว่า CMN ทุกก้อนใหญ่ ความจริง 1% ในทารกนับรวมทุกขนาด ส่วนใหญ่เป็นก้อนเล็ก และชนิด giant พบน้อยมาก ความเสี่ยง melanoma ต่างกันมากตามขนาด ก้อนเล็กที่คงที่จึงไม่จำเป็นต้องตัดทุกก้อน",
 mnemonic="<b>‘ไฝแต่เกิด + เปลี่ยน 1 ข้อ = ตัดทั้งเม็ด ส่งตรวจ’</b>",
 guide="NCCN Clinical Practice Guidelines in Oncology: Melanoma: Cutaneous (2025); Krengel S, et al. Cutaneous congenital melanocytic nevi: proposed classification (J Am Acad Dermatol 2013;68:441–51); Bolognia Dermatology 4th ed. (2018) — Congenital melanocytic nevi",
 variants=[
  "ผลชิ้นเนื้อไฝแต่กำเนิดที่เปลี่ยนแปลงเป็น melanoma หนา 0.5 mm ไม่มีแผล → wide local excision ขอบ 1 cm โดยทั่วไปไม่ต้องทำ sentinel lymph node biopsy (T1a)",
  "เด็กอายุ 8 ปีมี medium CMN ขนาด 5 cm ที่แก้ม ไม่มีการเปลี่ยนแปลง ครอบครัวกังวลเรื่องรูปลักษณ์ → ผ่าตัดแบบ serial excision ได้ตามความเหมาะสม ไม่ใช่การผ่าตัดเร่งด่วนเพื่อมะเร็ง",
  "ชายอายุ 40 ปีมีปุ่มนูนแข็งสีชมพูโตเร็วขึ้นกลาง CMN ขนาดใหญ่ที่หลัง → ตัดชิ้นเนื้อปุ่มนั้นทันที เพราะ melanoma ใน CMN ใหญ่อาจเกิดเป็นก้อนในชั้นลึกโดยสีไม่เปลี่ยน"])

mk(Q, 87, [22, 70, 's14'],
 stem="A 30-year-old man has had a hairless, yellow-orange scalp plaque since birth. A firm nodule has recently appeared within it. Which malignant tumor has classically been linked to this lesion?",
 opts=["Basal cell carcinoma","Merkel cell carcinoma","Angiosarcoma","Malignant melanoma","Squamous cell carcinoma"],
 interp="ปื้นสีเหลืองส้มไม่มีผมบนหนังศีรษะตั้งแต่เกิด = nevus sebaceous of Jadassohn ผู้ใหญ่มีก้อนแข็งใหม่ขึ้นในปื้น = เนื้องอกที่เกิดซ้อนในรอยโรค → ถามมะเร็งที่ตำราผูกกับรอยโรคนี้ ต้องรู้ทั้งคำตอบคลาสสิกและข้อมูลใหม่ว่าเนื้องอกซ้อนส่วนใหญ่เป็น benign",
 why="<b>Nevus sebaceous of Jadassohn</b> เป็น <b>hamartoma ของต่อมไขมัน รูขุมขน และ apocrine gland</b> พบตั้งแต่แรกเกิด มักที่หนังศีรษะและใบหน้า (head &amp; neck) ลักษณะเป็นปื้นสีเหลืองส้มผิวมัน ขอบชัด ไม่มีผม และเปลี่ยนตามวัย: วัยทารกแบนเรียบ → วัยรุ่นหนาขึ้นเป็นตุ่มละเอียดคล้าย cobblestone ตามฮอร์โมน → ผู้ใหญ่อาจมี<b>เนื้องอกเกิดซ้อนในรอยโรค (secondary neoplasm)</b> · มะเร็งที่ตำราคลาสสิกผูกไว้คือ <b>basal cell carcinoma</b> แต่การศึกษาใหม่ที่ใช้เกณฑ์พยาธิปัจจุบันพบ BCC จริงเพียงราว 1% เนื้องอกซ้อนส่วนใหญ่เป็น<b>ชนิด benign</b> คือ <b>trichoblastoma</b> และ <b>syringocystadenoma papilliferum</b> และรายงานเก่าหลายรายน่าจะวินิจฉัย trichoblastoma เป็น BCC · ก้อนใหม่ที่ขึ้นในปื้นจึงต้อง<b>ตัดออกส่งตรวจ</b> และการตัดทั้งปื้นทำได้ด้วยขอบแคบ ไม่ต้องตัดกว้าง · สไลด์หน้า 22 ลายมือ <b>“เสี่ยง basal cell carcinoma → ตัด lesion พอ (ไม่ต้อง wide excision)”</b>",
 wrong={
  "B":"Merkel cell carcinoma เป็นมะเร็ง neuroendocrine ของผิวที่รุนแรง มักเป็นก้อนแดงม่วงโตเร็วไม่เจ็บบนผิวที่ถูกแดดของผู้สูงอายุหรือผู้ที่ภูมิคุ้มกันต่ำ สัมพันธ์กับ Merkel cell polyomavirus และแสง UV ไม่ได้เกิดจากรอยโรคแต่กำเนิด · ไม่มีสถานการณ์ใดที่ Merkel cell carcinoma ถูกสอนว่าเป็นมะเร็งที่เกิดจากรอยโรคนำบนผิวชนิดใดชนิดหนึ่ง เพราะเกิดขึ้นบนผิวที่เคยปกติจากไวรัสหรือ UV ไม่มี precursor lesion ที่ตำรารับรอง",
  "C":"Angiosarcoma เป็นมะเร็งของเซลล์บุหลอดเลือด ในผู้สูงอายุมักเป็นปื้นช้ำม่วงที่หนังศีรษะและใบหน้าบนผิวที่เคยปกติ ไม่ได้เกิดจาก nevus sebaceous · จะถูกถ้าหญิงที่เคยผ่าตัดเต้านมและเลาะต่อมน้ำเหลืองรักแร้มีแขนบวมเรื้อรังมา 10 ปี แล้วเกิดตุ่มสีม่วงช้ำหลายจุดที่แขนข้างนั้น (Stewart–Treves syndrome) ซึ่งมะเร็งที่ผูกกับ chronic lymphedema คือ angiosarcoma",
  "D":"Melanoma เกิดจาก melanocyte ส่วน nevus sebaceous เป็นความผิดปกติของต่อมไขมันและรูขุมขน ไม่มี melanocyte ผิดปกติเป็นองค์ประกอบหลัก จึงไม่ใช่รอยโรคนำของ melanoma · จะถูกถ้าเด็กชายอายุ 6 ปีมีไฝแต่กำเนิดขนาดใหญ่กว่า 40 cm คลุมหลังและก้นพร้อม satellite nevi จำนวนมาก (giant congenital melanocytic nevus) ซึ่งมะเร็งที่ตำราผูกกับรอยโรคนี้คือ melanoma",
  "E":"SCC เกิดใน nevus sebaceous ได้แต่พบน้อยมาก ไม่ใช่มะเร็งที่ตำราคลาสสิกผูกกับรอยโรคนี้ SCC มีรอยโรคนำของตัวเอง เช่น actinic keratosis และแผลเป็นเรื้อรัง · จะถูกถ้าชายอายุ 60 ปีมีแผลเป็นจากไฟไหม้ที่ขาตั้งแต่เด็ก แผลแตกเรื้อรังและมีก้อนนูนขอบม้วนออกขึ้นในแผล (Marjolin ulcer) ซึ่งมะเร็งที่ผูกกับแผลเป็นเรื้อรังคือ SCC"},
 trap="รู้ว่าเนื้องอกซ้อนส่วนใหญ่เป็น benign แล้วอาจลังเลไปเลือกมะเร็งอื่นที่ดูรุนแรงกว่า หรือคิดว่ารอยโรคแต่กำเนิดต้องผูกกับ melanoma · ตัวแยก: คำถามถามมะเร็งที่<b>ผูกไว้แบบคลาสสิก</b> ซึ่งคือ BCC ตามลายมือหน้า 22 แม้ข้อมูลใหม่จะพบน้อยกว่าที่เคยเชื่อ",
 summary=[
  "แกน: nevus sebaceous → มะเร็งคลาสสิกคือ BCC (ลายมือหน้า 22) แต่ข้อมูลปัจจุบันพบ BCC จริงเพียงราว 1%",
  "เนื้องอกซ้อนที่พบบ่อยจริง: trichoblastoma และ syringocystadenoma papilliferum ซึ่งเป็น benign",
  "ลักษณะ: ปื้นสีเหลืองส้มไม่มีผม ผิวมัน ขอบชัด ตั้งแต่เกิด ที่ศีรษะและคอ · วัยรุ่นหนาเป็นตุ่มแบบ cobblestone",
  "ลายมือหน้า 70: เป็น premalignant → excision · ลายมือหน้า 22: ตัด lesion พอ ไม่ต้อง wide excision",
  "ชีทหน้า 14: กลายเป็นเนื้อร้ายราว 10–15% ส่วนใหญ่เป็น BCC และเปลี่ยนแปลงช่วงวัยรุ่น ซึ่งเป็นตัวเลขยุคเก่า",
  "ก้อนใหม่ในปื้น → ตัดส่งตรวจ · ปื้นที่คงที่ ตัดป้องกันหรือเฝ้าดูได้ตามตำแหน่งและความต้องการ"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจปานกลางถึงสูง — คำถามถามมะเร็งที่ผูกไว้แบบคลาสสิก ซึ่งลายมือสไลด์หน้า 22 และชีทหน้า 14 ระบุว่าเป็น BCC · จุดที่ต่างจากหลักฐานปัจจุบัน: ชีทหน้า 14 ให้กลายเป็นเนื้อร้าย 10–15% ส่วนใหญ่เป็น BCC แต่การทบทวนชุดผู้ป่วย 707 รายของ Idriss และ Elston (J Am Acad Dermatol 2014) พบ BCC เพียงราว 1% เนื้องอกซ้อนส่วนใหญ่เป็น trichoblastoma และ syringocystadenoma papilliferum · ลายมือสไลด์หน้า 70 ที่เขียนว่าเป็น premalignant ต้องตัดจึงเป็นแนวคิดเดิม ปัจจุบันการตัดป้องกันในเด็กที่ปื้นคงที่ไม่ใช่ข้อบังคับ ตัดเมื่อมีก้อนใหม่ เพื่อความสวยงาม หรือเมื่อติดตามยาก",
 mnemonic="<b>‘Jadassohn: ตำราว่า BCC แต่ชิ้นเนื้อจริงมักเป็น trichoblastoma กับ SCAP’</b>",
 guide="Idriss MH, Elston DM. Secondary neoplasms associated with nevus sebaceus of Jadassohn: a study of 707 cases (J Am Acad Dermatol 2014;70:332–7); Bolognia Dermatology 4th ed. (2018) — Nevus sebaceus",
 variants=[
  "ทารกอายุ 6 เดือนมีปื้นสีเหลืองส้มแบนเรียบไม่มีผมขนาด 2 cm ที่หนังศีรษะ ไม่มีก้อน → เฝ้าดูได้ อธิบายว่าจะหนาขึ้นช่วงวัยรุ่น การตัดเป็นทางเลือกที่ไม่เร่งด่วน",
  "เด็กมี nevus sebaceous เป็นแผ่นยาวตามแนวกลางใบหน้า ร่วมกับชัก พัฒนาการช้า และความผิดปกติของตา → linear nevus sebaceous syndrome (Schimmelpenning) ส่งตรวจระบบประสาทและตา",
  "ตัดปื้น nevus sebaceous ที่หนังศีรษะพร้อมก้อนใหม่ ผลพยาธิเป็น trichoblastoma ขอบปลอด → ไม่ต้องรักษาเพิ่มและไม่ต้องตัดกว้าง"])

mk(Q, 88, [7],
 stem="A 69-year-old man has a 1-cm crater-shaped nodule with a keratin plug on the hand that grew within 4 weeks. A colleague advises leaving it alone because it will regress. What is the best response?",
 opts=["Radiotherapy without biopsy, as these tumors are radiosensitive and often regress","Agree and discharge without any follow-up","A course of oral antibiotics for presumed infection","Intralesional corticosteroid injection alone","Excise it fully for histology to exclude squamous cell carcinoma"],
 interp="ก้อนปล่องมี keratin อุดที่หลังมือ โตเร็วใน 4 สัปดาห์ = เข้าได้กับ keratoacanthoma ซึ่งอาจยุบเองได้ → ถามว่าควรตอบเพื่อนแพทย์ที่จะปล่อยไว้อย่างไร ต้องใช้หลักว่า KA แยกจาก SCC ด้วยตาไม่ได้ ต้องได้ชิ้นเนื้อทั้งก้อนก่อนวางใจ",
 why="KA มีจุดเด่นคือ<b>โตเร็วใน 2–8 สัปดาห์แล้วอาจยุบเองในหลายเดือน</b> แต่ความจริงที่ทำให้ปล่อยไว้ไม่ได้คือ <b>ลักษณะทางคลินิกแยกจาก well-differentiated SCC ไม่ได้</b> ทั้งก้อนโดมโตเร็วและแกน keratin ก็พบใน SCC ได้ แม้ทางพยาธิก็แยกได้ยาก ต้องเห็น<b>โครงสร้างทั้งก้อน</b>ตั้งแต่ขอบถึงฐาน (รูปถ้วย มีขอบเยื่อบุยื่นคลุม ฐานเรียบ) จึงจะแยกได้ · ตำราหลายเล่มและ WHO จัด KA เป็นชนิดย่อยของ SCC และบางก้อนลุกลามหรือแพร่กระจายได้ · การรอให้ยุบยังทิ้งแผลเป็นบุ๋มที่อาจแย่กว่าแผลผ่าตัด และก้อนที่มือหรือหน้าอาจทำลายโครงสร้างระหว่างโต · แนวทางจึงเป็น<b>การตัดออกทั้งก้อนพร้อมฐาน (complete excision)</b> ด้วยขอบแบบ cSCC ความเสี่ยงต่ำ 4–6 mm แล้วส่งตรวจ ซึ่งเป็นทั้งการวินิจฉัยและการรักษา ถ้าตัดทั้งก้อนไม่ได้ทำ deep incisional biopsy ที่ได้ถึงฐานก้อน ไม่ใช้ shave ตื้น · สไลด์หน้า 7 ลายมือ <b>“· ถ้าก้อนใหญ่ : อาจสับสนกับ squamous cell carcinoma (ลอง bx ไปตรวจ)”</b>",
 wrong={
  "A":"การฉายรังสีเป็นทางเลือกของ KA หรือ cSCC ที่ผ่าตัดไม่ได้ แต่ต้องมีผลชิ้นเนื้อก่อน เพราะต้องรู้ชนิดเนื้องอกเพื่อกำหนดปริมาณรังสี ขอบเขต และการติดตาม และการยุบเองไม่ได้แปลว่าไวต่อรังสี · ไม่มีสถานการณ์ใดที่ก้อนผิวหนังซึ่งยังแยกจากมะเร็งไม่ได้ควรส่งฉายรังสีโดยไม่มีชิ้นเนื้อยืนยัน เพราะการรักษามะเร็งด้วยรังสีต้องอาศัยการวินิจฉัยทางพยาธิก่อนเสมอ",
  "B":"การจำหน่ายโดยไม่ติดตามเชื่อว่าก้อนจะยุบเองแน่นอน ทั้งที่แยกจาก SCC ไม่ได้ ถ้าเป็น SCC จะลุกลามต่อและอาจกระจายไปต่อมน้ำเหลือง · จะถูกถ้าทารกแรกเกิดมีปื้นสีชมพูแดงจาง ๆ ที่หนังตาบนและกลางหน้าผาก (nevus simplex หรือ salmon patch) ซึ่งจางหายเองภายใน 1–2 ปีโดยไม่มีความเสี่ยง ให้ความมั่นใจแก่ครอบครัวแล้วจำหน่ายได้",
  "C":"ยาปฏิชีวนะใช้กับการติดเชื้อแบคทีเรีย ก้อนที่มีแกน keratin โตเร็วโดยไม่มีไข้ ไม่มีหนอง ไม่แดงร้อนรอบก้อน ไม่ใช่ภาพการติดเชื้อ การให้ยาจะทำให้วินิจฉัยช้า · จะถูกถ้าชายมีผื่นแดงร้อนบวมกดเจ็บที่หลังมือ ขอบไม่ชัด ลามขึ้นแขนใน 2 วันหลังถูกหนามตำ ไม่มีโพรงหนอง (cellulitis) ซึ่งรักษาด้วยยาปฏิชีวนะชนิดกินที่คลุม streptococcus และ <i>S. aureus</i>",
  "D":"การฉีด steroid เข้ารอยโรคใช้ลดการสร้างคอลลาเจนในแผลเป็นนูน ไม่ใช่การรักษาเนื้องอก squamous และไม่ได้ชิ้นเนื้อเพื่อแยก SCC (ยาฉีดเข้ารอยโรคที่มีข้อมูลใน KA คือ methotrexate หรือ 5-FU ไม่ใช่ steroid) · จะถูกถ้าหญิงอายุ 22 ปีมีก้อนแผลเป็นนูนแข็งเกินขอบแผลเดิมที่ติ่งหูหลังเจาะหู 6 เดือน คันและเจ็บ (keloid) ซึ่งการฉีด triamcinolone เข้ารอยโรคเป็นการรักษาลำดับแรก"},
 trap="ความรู้ว่า KA ยุบเองได้ทำให้การรอดูเหมือนเป็นทางเลือกที่ถูกและประหยัด · ตัวแยก: คำถามเรื่องการจัดการไม่ได้ถามธรรมชาติของโรค ก้อนที่<b>อาจเป็น SCC</b> ต้องได้ชิ้นเนื้อทั้งก้อนก่อนเสมอ การยุบเองได้เป็นเหตุผลที่ไม่พอ",
 summary=[
  "แกน: ก้อนที่ดูเป็น KA ต้องตัดออกทั้งก้อนส่งตรวจ เพราะแยกจาก well-differentiated SCC ทางคลินิกไม่ได้",
  "พยาธิแยก KA จาก SCC ต้องเห็นโครงสร้างทั้งก้อน: รูปถ้วย ขอบเยื่อบุยื่นคลุม แกน keratin ฐานเรียบ → ห้าม shave ตื้น",
  "ถ้าตัดทั้งก้อนไม่ได้ทันที: deep incisional หรือ punch ผ่านกลางก้อนให้ถึงฐาน",
  "ขอบตัดใช้แบบ cSCC ความเสี่ยงต่ำ 4–6 mm",
  "KA ในตำแหน่งที่ผ่าตัดยาก: methotrexate หรือ 5-FU ฉีดเข้ารอยโรคเป็นทางเลือก หลังได้ชิ้นเนื้อยืนยัน",
  "การยุบเองใช้เวลาหลายเดือนและทิ้งแผลเป็นบุ๋ม ไม่ได้ปลอดภัยหรือสวยกว่าการตัด"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ลายมือสไลด์หน้า 7 ระบุว่าก้อนใหญ่อาจสับสนกับ SCC ให้ bx ไปตรวจ และ NCCN Squamous Cell Skin Cancer (2025) จัดการ KA แบบเดียวกับ cSCC · จุดที่ลายมือต่างจากแนวทางปัจจุบันเล็กน้อย: ลายมือเน้นเฉพาะก้อนใหญ่ แต่แนวทางปัจจุบันให้ตัดตรวจทุกก้อนที่สงสัย KA ไม่ว่าขนาดใด เพราะแม้ก้อนเล็กก็แยกจาก SCC ไม่ได้ และควรเป็นการตัดทั้งก้อนมากกว่าตัดบางส่วน เพื่อให้พยาธิเห็นโครงสร้างครบ",
 mnemonic="<b>‘KA อาจยุบ แต่ SCC ไม่ยุบ: แยกไม่ได้ = ตัดตรวจ’</b>",
 guide="NCCN Clinical Practice Guidelines in Oncology: Squamous Cell Skin Cancer (2025); WHO Classification of Skin Tumours 4th ed. (2018); Bolognia Dermatology 4th ed. (2018) — Keratoacanthoma",
 variants=[
  "ผล shave biopsy ผิวตื้นของก้อนปล่องที่แก้มรายงานว่าเป็น well-differentiated squamous proliferation แยก KA กับ SCC ไม่ได้ → ตัดทั้งก้อนพร้อมฐานส่งตรวจซ้ำ",
  "ผลชิ้นเนื้อหลังตัด KA ที่หลังมือ ขอบปลอดทุกด้าน → ติดตามผิวหนังเป็นระยะเหมือน cSCC ความเสี่ยงต่ำ ไม่ต้องรักษาเพิ่ม",
  "ชายที่ได้ยากดภูมิหลังปลูกถ่ายไตมีก้อนแบบ KA ขึ้นหลายก้อนที่หน้า → จัดการแบบ cSCC ความเสี่ยงสูง ตัดตรวจทุกก้อน และปรับยากดภูมิร่วมกับแพทย์ปลูกถ่าย"])

mk(Q, 89, [9, 's11'],
 stem="Over 4 months, a mole on a 38-year-old woman's back has thickened and changed shape. What is appropriate?",
 opts=["Excisional biopsy with a narrow margin","Wait until it bleeds or ulcerates","Reassurance, as it is neither itchy nor bleeding","Topical hydroquinone bleaching cream","Laser ablation without obtaining histology"],
 interp="ไฝที่หลังหนาขึ้นและเปลี่ยนรูปร่างใน 4 เดือน แม้ไม่คันและไม่มีเลือดออก = มี cardinal sign ข้อ change in size, shape or thickness → ถามขั้นต่อไป ต้องรู้ว่า cardinal sign ข้อเดียวพอให้ตัดชิ้นเนื้อ และวิธี biopsy ที่ถูกสำหรับรอยโรคสงสัย melanoma",
 why="การเปลี่ยนแปลงของไฝ (<b>Evolution</b>) เป็นสัญญาณที่ไวที่สุดของ melanoma โดยเฉพาะ<b>ขนาด รูปร่าง หรือความหนาที่เพิ่มขึ้น</b> ซึ่งความหนาบ่งว่าเซลล์เริ่มลงลึกในแนวตั้ง (vertical growth) · cardinal sign <b>ข้อเดียวก็พอเป็นข้อบ่งชี้ biopsy</b> ไม่ต้องรอให้คัน เลือดออก หรือเป็นแผล ซึ่งมักบ่งว่าก้อนลึกและพยากรณ์แย่ลงแล้ว · nodular melanoma มักไม่เข้า ABCD แต่ใช้เกณฑ์ <b>EFG: Elevated, Firm, Growing</b> นานกว่า 1 เดือน · วิธีที่ถูกคือ <b>excisional biopsy ขอบแคบ 1–3 mm ลึกถึงไขมันใต้ผิว</b> วางแนวแผลให้ตัดกว้างตามได้ เพื่อให้พยาธิวัด <b>Breslow thickness</b> ulceration และ mitosis ได้ครบ ไม่ทำ wide excision ทันทีเพราะอาจรบกวนการทำ sentinel lymph node biopsy ภายหลัง · ชีทหน้า 11 สำหรับไฝผิดปกติ <b>“ถ้าไฝเม็ดใดมีการเปลี่ยนแปลงจะต้องได้รับการตัดชิ้นเนื้อตรวจ (biopsy)”</b> · สไลด์หน้า 9 <b>“Change in size , shape , or thickness”</b> และลายมือ <b>“= ควร bx ส่งตรวจ”</b>",
 wrong={
  "B":"การรอให้เลือดออกหรือเป็นแผลคือรอให้ถึง cardinal sign ระยะท้าย เลือดออกและ ulceration บ่งว่าก้อนลึก และ ulceration เพิ่มระยะ T ใน AJCC ทำให้พยากรณ์แย่ลง · ไม่มีสถานการณ์ใดที่การรอให้ไฝเลือดออกหรือเป็นแผลก่อนตัดตรวจเป็นแนวทางที่ถูก เพราะทุกแนวทางตั้งเป้าวินิจฉัย melanoma ก่อนเกิด ulceration และ cardinal sign ข้อใดข้อหนึ่งก็พอให้ biopsy",
  "C":"การไม่คันและไม่มีเลือดออกบอกแค่ว่าไม่มี cardinal sign สองข้อ แต่การเปลี่ยนรูปร่างและความหนาเป็น cardinal sign อีกข้อที่นับแยกกัน · ไม่มีสถานการณ์ใดที่การไม่คันและไม่มีเลือดออกเพียงอย่างเดียวเป็นเหตุผลพอให้วางใจไฝ เพราะการวางใจต้องอาศัยว่าไฝคงที่และไม่มี cardinal sign เลยทุกข้อ ไม่ใช่แค่ไม่มีบางอาการ",
  "D":"Hydroquinone ลดการสร้างเม็ดสีของ melanocyte ใช้กับรอยดำที่ไม่ใช่เนื้องอก ไม่ได้รักษาไฝ และการทำให้สีจางลงยังกลบการเปลี่ยนแปลงที่ต้องเฝ้าดู · จะถูกถ้าหญิงอายุ 35 ปีมีปื้นสีน้ำตาลที่โหนกแก้มสองข้างสมมาตร เข้มขึ้นหลังตั้งครรภ์และเมื่อโดนแดด (melasma) ซึ่งรักษาด้วยครีม hydroquinone ร่วมกับยากันแดด",
  "E":"Laser ทำลายเม็ดสีและเนื้อเยื่อโดยไม่มีชิ้นเนื้อ ถ้าเป็น melanoma จะไม่รู้ความหนา ไม่รู้ระยะ และอาจเหลือเซลล์ในชั้นลึกที่โตต่อโดยมองไม่เห็น · จะถูกถ้าหญิงมีปื้นสีเทาอมฟ้าที่ขมับและรอบตาข้างเดียวตั้งแต่เด็ก ตาขาวข้างนั้นมีสีเทา (nevus of Ota) ซึ่งวินิจฉัยได้จากลักษณะและรักษาด้วย Q-switched หรือ picosecond laser"},
 trap="การไม่มีอาการคันหรือเลือดออกทำให้รู้สึกว่าไฝยังไม่น่ากลัว เพราะสองอาการนี้จำง่ายที่สุด · ตัวแยก: cardinal sign <b>แต่ละข้อนับแยกกัน</b> การเปลี่ยนขนาด รูปร่าง หรือความหนาเป็นข้อแรกในรายการและสำคัญที่สุด ข้อเดียวก็พอให้ตัดตรวจ",
 summary=[
  "แกน: ไฝที่ขนาด รูปร่าง หรือความหนาเปลี่ยน = cardinal sign ข้อเดียวพอ → excisional biopsy",
  "Excisional biopsy: ขอบ 1–3 mm ลึกถึงไขมัน · วางแนวให้ตัดกว้างตามได้ · หลีกเลี่ยง wide excision ก่อนรู้ผล",
  "ABCDE: Asymmetry · Border · Color · Diameter (สไลด์ใช้ &gt; 6 mm แต่ชีทหน้า 11 ใช้ &gt; 8 mm) · Evolution",
  "EFG สำหรับ nodular melanoma: Elevated · Firm · Growing นานกว่า 1 เดือน",
  "ชีทหน้า 11: dysplastic nevus เสี่ยง melanoma 6% ถ้าไม่มีประวัติครอบครัว 15% ถ้ามี · ไฝจำนวนมากใช้ total-body photography",
  "เลือดออกหรือ ulceration เป็นสัญญาณช้า และ ulceration ทำให้ T stage สูงขึ้น"],
 opinion="เห็นด้วยกับคำตอบ A ความมั่นใจสูง — สไลด์หน้า 9 ให้ change in size, shape or thickness เป็น cardinal sign ข้อหนึ่งและลายมือเขียนว่าควร bx ส่งตรวจ ชีทหน้า 11 ก็ให้ไฝที่เปลี่ยนแปลงต้องตัดชิ้นเนื้อ · NCCN Melanoma (2025) แนะนำ excisional biopsy ขอบ 1–3 mm เป็นวิธีที่ดีที่สุด · จุดที่ต่างกันระหว่างแหล่ง: ชีทหน้า 11 ใช้เกณฑ์ D &gt; 8 mm ขณะที่สไลด์และแนวทางสากลใช้ &gt; 6 mm และรายการ cardinal sign บนสไลด์หน้า 9 ไม่ได้แยกตัว E (Evolution) ออกมา แต่ข้อ change ทั้งหมดมีความหมายเดียวกัน",
 mnemonic="<b>‘เปลี่ยน 1 ข้อ = ตัด 1 เม็ด (ขอบ 1–3 mm)’</b>",
 guide="NCCN Clinical Practice Guidelines in Oncology: Melanoma: Cutaneous (2025); AJCC Cancer Staging Manual 8th ed. (2017) — Melanoma of the skin; Abbasi NR, et al. Early diagnosis of cutaneous melanoma: revisiting the ABCD criteria (JAMA 2004;292:2771–6)",
 variants=[
  "แผ่นสีน้ำตาลไม่สม่ำเสมอกว้าง 4 cm ที่แก้มผู้สูงอายุซึ่งสงสัย lentigo maligna → biopsy หลายจุดหรือ broad shave ตรงส่วนที่สงสัย เพราะตัดทั้งแผ่นเพื่อวินิจฉัยทำไม่ได้",
  "แถบสีดำตามยาวที่เล็บโป้งกว้างขึ้นและสีลามไปที่ผิวรอบเล็บ (Hutchinson sign) → biopsy ที่ nail matrix สงสัย subungual melanoma",
  "ผล excisional biopsy เป็น melanoma หนา 1.2 mm → wide local excision ขอบ 1–2 cm และเสนอ sentinel lymph node biopsy",
  "ไฝเม็ดหนึ่งที่หลังหน้าตาต่างจากไฝเม็ดอื่นทั้งหมด (ugly duckling sign) → ตัดตรวจแม้ยังไม่เข้า ABCD ชัด"])

mk(Q, 90, [10, 12, 13, 's13'],
 stem="A 2-cm smooth subcutaneous nodule is found on a man's back. Which finding favors an epidermal cyst over a lipoma?",
 opts=["Lobulated outline on palpation","Slow growth over several years","Free mobility beneath skin with no skin tethering","Soft, doughy consistency","Skin tethering with a central punctum"],
 interp="ก้อนใต้ผิวเรียบขนาด 2 cm ที่หลัง แยกโรคหลักระหว่าง epidermal cyst กับ lipoma → ถามลักษณะที่ชี้ไปทาง cyst ต้องใช้กายวิภาค: cyst เกิดจากรูขุมขนอุดตันจึงติดผิวด้านบนตรงรูเปิด ส่วน lipoma อยู่ในชั้นไขมันจึงไม่ติดผิว",
 why="<b>Epidermal (epidermoid) cyst</b> ซึ่งเรียกผิดว่า sebaceous cyst เกิดจาก<b>การอุดตันของ pilosebaceous unit</b> ผนังเป็น stratified squamous epithelium สร้าง keratin สะสมตรงกลาง (ไม่ใช่ sebum) ถุงจึง<b>ต่อกับผิวด้านบนผ่านรูเปิดที่อุดตัน</b> เห็นเป็น<b>จุดดำหรือรูบุ๋มตรงกลาง (punctum)</b> เมื่อจับผิวขยับ ก้อนจะขยับตามผิว ส่วนด้านล่างไม่ติด เนื้อก้อนแน่นตึงถึงหยุ่น · <b>Lipoma</b> เป็นเนื้องอกของเซลล์ไขมันในชั้น subcutaneous ไม่ได้เกิดจากผิว จึง<b>ไม่ติดผิวด้านบน</b> ผิวขยับเหนือก้อนได้อิสระ คลำได้นุ่มหยุ่นเป็นพู ขอบเลื่อนหลุดใต้นิ้ว · ผลต่อการผ่าตัด: cyst ต้อง<b>ตัดผิวรูปรีรอบ punctum พร้อมถุงทั้งใบ</b> มิฉะนั้นเป็นซ้ำ ส่วน lipoma กรีดผิวแล้วเอาก้อนออกได้โดยไม่ต้องตัดผิว · ถ้าคลำแยกไม่ได้ ultrasound ช่วยได้: cyst เป็นก้อนขอบชัด echo ต่ำ มี posterior acoustic enhancement และอาจเห็นทางเชื่อมขึ้นผิว · ชีทหน้า 13 <b>“มีรอยบุ๋มตรงกลางเป็นรูเปิดที่อุดตัน”</b> · สไลด์หน้า 12 ลายมือ <b>“· ก้อนติดผิว (ติดรูขุมขน) ไม่ติดข้างล่าง”</b>",
 wrong={
  "A":"ขอบเป็นพูเป็นลักษณะของ lipoma ซึ่งประกอบด้วยก้อนไขมันหลายกลีบคั่นด้วยผนังบาง ส่วน epidermal cyst เป็นถุงใบเดียวขอบมักกลมเรียบ ลักษณะนี้จึงชี้ไปทางตรงข้าม · ไม่มีสถานการณ์ใดที่ขอบเป็นพูชี้ว่าก้อนเป็น epidermal cyst มากกว่า lipoma เพราะถุงของ cyst มีผนัง epithelium ล้อมรอบ keratin เป็นช่องเดียว ส่วนความเป็นพูเป็นคุณสมบัติของเนื้อไขมัน",
  "B":"การโตช้าเป็นปีพบได้ทั้ง epidermal cyst และ lipoma ซึ่งต่างก็เป็นก้อน benign ที่โตช้า ลักษณะนี้บอกว่าน่าจะไม่ใช่มะเร็ง แต่ไม่ได้แยกระหว่างสองโรค · ไม่มีสถานการณ์ใดที่การโตช้าเพียงอย่างเดียวแยก epidermal cyst จาก lipoma ได้ เพราะเป็นคุณสมบัติร่วมของทั้งสองโรค ส่วนการโตเร็วต่างหากที่ต้องระวัง เพราะชวนสงสัย liposarcoma หรือ cyst ที่อักเสบ",
  "C":"การโยกได้อิสระใต้ผิวโดยไม่ติดผิวเป็นลักษณะเด่นของ lipoma ตามลายมือสไลด์หน้า 10 จึงชี้ไปทางตรงข้ามกับคำถาม · ไม่มีสถานการณ์ใดที่ก้อนซึ่งไม่ติดผิวเลยชี้ว่าเป็น epidermal cyst มากกว่า lipoma เพราะ cyst ส่วนใหญ่เกิดจากรูขุมขนที่อุดตันและต่อกับผิวด้านบน การไม่ติดผิวเลยจึงเพิ่มน้ำหนักให้ lipoma ไม่ใช่ cyst",
  "D":"ความนุ่มแบบแป้งนวดเข้ากับ lipoma มากกว่า ส่วน epidermal cyst มักแน่นตึงถึงหยุ่นจาก keratin ข้างใน แต่ความแข็งนุ่มเปลี่ยนตามความตึงของถุงและความลึก จึงเป็นตัวแยกที่อ่อน · ไม่มีสถานการณ์ใดที่ความนุ่มแบบแป้งนวดชี้ไปทาง epidermal cyst มากกว่า lipoma เพราะถ้าความนุ่มจะเอียงไปทางใด ก็เอียงไปทาง lipoma"},
 trap="ทั้งสองก้อนเรียบ โตช้า ไม่เจ็บ จึงชวนเลือกลักษณะที่จำได้จากก้อนใดก้อนหนึ่งโดยไม่ดูว่าชี้ไปทางไหน · ตัวแยกคือ<b>ความสัมพันธ์กับผิว</b>: cyst ติดผิวด้านบนตรง punctum เพราะเกิดจากรูขุมขน lipoma ไม่ติดผิวเพราะเกิดในชั้นไขมัน ช้อยที่เหลือเป็นของ lipoma หรือเป็นของทั้งคู่",
 summary=[
  "แกน: ติดผิวด้านบน + central punctum = epidermal cyst · ไม่ติดผิว โยกได้ เป็นพู นุ่ม = lipoma",
  "Epidermal cyst: pilosebaceous unit อุดตัน · ผนัง stratified squamous · ข้างในเป็น keratin (sebaceous cyst เป็น misnomer) · พบที่หน้า หลัง หู หน้าอก",
  "Lipoma: เนื้องอก subcutaneous ที่พบบ่อยที่สุด · ไม่เสี่ยงเป็นมะเร็ง · ก้อนใหญ่หรือโตเร็วนึกถึง liposarcoma",
  "Ultrasound: cyst ขอบชัด echo ต่ำ posterior enhancement · lipoma echo ใกล้เคียงไขมันรอบ มีเส้น echo ขนานผิว กดยุบได้",
  "ผ่าตัด: cyst ตัดผิวรูปรีรอบ punctum + ถุงทั้งใบ · lipoma กรีดผิวแล้วเอาก้อนออก ไม่ต้องตัดผิว",
  "ญาติของ epidermal cyst: dermoid (แต่กำเนิด หางคิ้ว) · trichilemmal (หนังศีรษะ ไม่มี punctum keratin แห้ง)"],
 opinion="เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ลายมือสไลด์หน้า 12 ให้ cyst ติดผิวที่รูขุมขนแต่ไม่ติดข้างล่าง และลายมือสไลด์หน้า 13 ว่า cyst ติดขนด้านบนจึงต้องตัดผิวออกด้วย ตรงข้ามกับลายมือสไลด์หน้า 10 ที่ให้ lipoma โยกได้ไม่ติดผิว · ข้อควรรู้เพิ่มจากตำรา: punctum ไม่ได้เห็นชัดในทุก cyst การไม่เห็น punctum จึงไม่ตัด cyst ออก ให้ทดสอบโดยบีบผิวเหนือก้อนดูว่าผิวติดหรือไม่ และใช้ ultrasound เมื่อก้อนอยู่ลึกหรือแยกยาก · หัวสไลด์ใช้คำว่า Sebaceous Cyst ซึ่งชีทหน้า 13 อธิบายว่าเป็น misnomer เพราะข้างในเป็น keratin ไม่ใช่ sebum",
 mnemonic="<b>‘Cyst ติดผิว มีรูกลาง · Lipoma ลอยใต้ผิว เป็นพู’</b>",
 guide="Sabiston Textbook of Surgery 21st ed. (2022) — Skin and subcutaneous tissue; Bolognia Dermatology 4th ed. (2018) — Cysts and lipomas",
 variants=[
  "เด็กชายอายุ 10 ปีมี epidermal cyst หลายก้อนที่หน้าและลำตัว ร่วมกับ osteoma ที่ขากรรไกร และพ่อเป็นมะเร็งลำไส้ใหญ่ตั้งแต่อายุน้อย → Gardner syndrome (FAP) ส่งส่องกล้องลำไส้",
  "ชายหนุ่มมีก้อนนุ่มเป็นพูใต้ผิวหลายก้อนที่ปลายแขน กดแล้วเจ็บ → angiolipoma ตัดออกเมื่อปวด",
  "ก้อนใต้ผิวที่หน้าผากแน่น ไม่ติดผิว โยกได้น้อย อยู่ใต้กล้ามเนื้อ frontalis → subgaleal lipoma ต้องผ่าผ่านชั้นกล้ามเนื้อเพื่อเอาออก ไม่ใช่ cyst"])

save(Q, 'parts/fill/l22_r09.json')
